-- Athena saved query (Product_B2C_Intl)
-- ID: 8483ead6-0355-4b30-9f4a-9b6d7dd90cc9
-- Name: MH vs India Funnel Overall - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH -- short_routes AS ( -- SELECT DISTINCT src_id, dest_id -- FROM lis.short_route_sds -- WHERE cohort = '2026' -- ), -- Deduped Funnel Steps (1 row per session + route) srp_deduped AS ( SELECT DISTINCT s.mri_session_id, s.route_id, s.rb_user_id, s.user_type, s.os, s.channel, s.src_id, s.dest_id, op_id, cl.region, -- CASE WHEN sr.src_id IS NOT NULL THEN 'Short Routes' ELSE 'Long Routes' END AS route_type, CAST(DATE_TRUNC('day', at_timezone(s.__time, 'Asia/Kolkata')) AS DATE) AS doi, date_format(at_timezone(s.__time, 'Asia/Kolkata'), '%Y-%b') AS month_period FROM "user_interaction"."search_route_details" s LEFT JOIN "lis"."config_locations" cl ON s.src_id = cl.id AND cl.geo = 'IND' -- LEFT JOIN short_routes sr ON s.src_id = sr.src_id AND s.dest_id = sr.dest_id WHERE s.__time >= TIMESTAMP '2025-12-31 18:30:00' AND s.__time < TIMESTAMP '2026-01-31 18:30:00' AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') -- AND s.os = 'Android' AND s.country = 'IND' -- GROUP BY 1,2,3,4,5,6,7,8,9 ), sl_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."seat_layout_details" WHERE __time >= TIMESTAMP '2025-12-31 18:30:00' AND __time < TIMESTAMP '2026-01-31 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), mpax_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."cust_info_details" WHERE __time >= TIMESTAMP '2025-12-31 18:30:00' AND __time < TIMESTAMP '2026-01-31 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), tco_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."create_order_details" WHERE __time >= TIMESTAMP '2025-12-31 18:30:00' AND __time < TIMESTAMP '2026-01-31 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), orderinfo_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."order_info_details" WHERE __time >= TIMESTAMP '2025-12-31 18:30:00' AND __time < TIMESTAMP '2026-01-31 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), addpay_deduped AS ( SELECT mri_session_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."make_payment_details" WHERE __time >= TIMESTAMP '2025-12-31 18:30:00' AND __time < TIMESTAMP '2026-01-31 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1 ), confirm_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id, SUM(tin_count) as tin_count FROM ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id, COUNT(DISTINCT tin) as tin_count FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2025-12-31 18:30:00' AND __time < TIMESTAMP '2026-01-31 18:30:00' AND country = 'IND' AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') GROUP BY 1,2 ) GROUP BY 1,2 ) SELECT -- 'MTD Dec 28' AS month_period, -- srp.doi, srp.month_period, CASE WHEN srp.os IS NULL THEN srp.channel ELSE srp.os END AS saleschannel, UPPER(srp.user_type) as user_type, -- srp.route_type, -- MH Funnel COUNT(DISTINCT CASE WHEN srp.region = 'Maharashtra and Goa' THEN srp.mri_session_id END) AS mh_srpload, COUNT(DISTINCT CASE WHEN srp.region = 'Maharashtra and Goa' THEN sl.mri_session_id END) AS mh_slload, COUNT(DISTINCT CASE WHEN srp.region = 'Maharashtra and Goa' THEN pax.mri_session_id END) AS mh_paxload, COUNT(DISTINCT CASE WHEN srp.region = 'Maharashtra and Goa' THEN tco.mri_session_id END) AS mh_tcoload, COUNT(DISTINCT CASE WHEN srp.region = 'Maharashtra and Goa' THEN oi.mri_session_id END) AS mh_paymentload, COUNT(DISTINCT CASE WHEN srp.region = 'Maharashtra and Goa' THEN ap.mri_session_id END) AS mh_addPayClick, COUNT(DISTINCT CASE WHEN srp.region = 'Maharashtra and Goa' THEN conf.mri_session_id END) AS mh_confirmsession, SUM(CASE WHEN srp.region = 'Maharashtra and Goa' THEN conf.tin_count END) AS mh_tin, -- PAN INDIA Funnel COUNT(DISTINCT srp.mri_session_id) AS srpload, COUNT(DISTINCT sl.mri_session_id) AS slload, COUNT(DISTINCT pax.mri_session_id) AS paxload, COUNT(DISTINCT tco.mri_session_id) AS tcoload, COUNT(DISTINCT oi.mri_session_id) AS paymentload, COUNT(DISTINCT ap.mri_session_id) AS addPayClick, COUNT(DISTINCT conf.mri_session_id) AS confirmsession, SUM(conf.tin_count) AS tin FROM srp_deduped srp LEFT JOIN sl_deduped sl ON srp.mri_session_id = sl.mri_session_id AND srp.route_id = sl.route_id LEFT JOIN mpax_deduped pax ON srp.mri_session_id = pax.mri_session_id AND srp.route_id = pax.route_id LEFT JOIN tco_deduped tco ON srp.mri_session_id = tco.mri_session_id AND srp.route_id = tco.route_id LEFT JOIN orderinfo_deduped oi ON srp.mri_session_id = oi.mri_session_id AND srp.route_id = oi.route_id LEFT JOIN addpay_deduped ap ON ap.mri_session_id = oi.mri_session_id LEFT JOIN confirm_deduped conf ON srp.mri_session_id = conf.mri_session_id AND srp.route_id = conf.route_id GROUP BY 1, 2, 3 ORDER BY 2, 3 DESC
